from sympy import sin, cos, tan, sec, csc, cot, pi

n = int(input())
for i in range(1, n + 1):
    name = input()
    d = int(input())
    x0 = d * pi / 180
    if (name == "tan" or name == "sec") and cos(x0) == 0:
        print(f"problem {i}: undefined")
    elif (name == "csc" or name == "cot") and sin(x0) == 0:
        print(f"problem {i}: undefined")
    else:
        if name == "tan":
            slope = sec(x0)**2
        elif name == "sec":
            slope = sec(x0) * tan(x0)
        elif name == "csc":
            slope = -csc(x0) * cot(x0)
        else:
            slope = -csc(x0)**2
        print(f"problem {i}: slope {slope}")
